["ps -ef | rg 'play1.py|run_navigation_benchmark.py' | rg -v rg || true","/home/fabu/HIMLoco"],
["git status --short && git diff --stat","/home/fabu/HIMLoco"],
["find assets/runs/navigation_benchmark/formal_30seed_camera_20260923 assets/runs/navigation_benchmark/flat_planning_30seed_20260924 assets/runs/navigation_benchmark/terrain_only_30seed_20260924 -maxdepth 1 -name '*_seed*.json' | awk -F/ '{count[$4]++} END {for (k in count) print k,count[k]}'","/home/fabu/HIMLoco"]
];
const rs=await Promise.all(cmds.map(([cmd,workdir])=>tools.exec_command({cmd,workdir,yield_time_ms:30000,max_output_tokens:5000}))); rs.forEach((r,i)=>text(`---${i+1}---\n${r.output}\nEXIT:${r.exit_code}`));
